@keyframes my-animation {
  0% {
    color: color-mix(in oklab, var(--color-emerald-600) 0%, transparent);
  }
  100% {
    color: color-mix(in oklab, var(--color-emerald-600) 0%, transparent);
  }
}

/* Standalone */
& {
  --x: 1;
}

/* In an at-rule */
@supports (--y: 1) {
  & {
    --x: 2;
  }
}

/* With :is(…) */
:is(&) {
  --x: 3;
}

/* In an at-rule, with :is(…) */
@supports (--y: 2) {
  :is(&) {
    --x: 4;
  }
}

/* With multiple selectors */
&,
.a {
  --x: 5;
}

/* With multiple selectors + :is(…) */
:is(&),
.b {
  --x: 6;
}

/* With multiple selectors in an at-rule */
@supports (--y: 3) {
  &,
  .c {
    --x: 7;
  }
}

/* With multiple selectors in an at-rule + :is(…) */
@supports (--y: 4) {
  :is(&),
  .d {
    --x: 8;
  }
}

.foo {
  .bar {
    @apply text-red-500 hover:text-red-600;
  }
}

.baz {
  @property --tw-content {
    syntax: '*';
    initial-value: '';
    inherits: false;
  }

  @property --tw-border-spacing-x {
    syntax: '<length>';
    inherits: false;
    initial-value: 0;
  }
}

.a::selection {
  & > * {
    @font-face {
      font-family: 'A';
    }
    @property --x {
      syntax: '*';
      inherits: false;
    }
    @scope (.from) {
      color: red;
    }
    @media (width >= 40rem) {
      :is(&, .b) {
        --x: 1;
      }
    }
  }
}

