/* Empty rule */
.foo {
}

/* Empty rule, with nesting */
.foo {
  .bar {
  }
  .baz {
  }
}

/* Empty rule, with special case '&' rules */
.foo {
  & {
    &:hover {
    }
    &:focus {
    }
  }
}

/* Empty at-rule */
@media (min-width: 768px) {
}

/* Empty at-rule with nesting*/
@media (min-width: 768px) {
  .foo {
  }

  @media (min-width: 1024px) {
    .bar {
    }
  }
}

/* Exceptions: */
@charset "UTF-8";
@layer foo, bar, baz;
@layer foo, bar, baz; /* Will be deduped */
@custom-media --modern (color), (hover);
@namespace 'http://www.w3.org/1999/xhtml';
@import url('https://fonts.googleapis.com/css2?family=Cedarville+Cursive&display=swap');

.foo {
  color: red;
  .bar {
    color: green;
    color: blue;
    color: green;
  }
  color: red;
}
.foo {
  color: red;
  & {
    color: green;
    & {
      color: red;
      color: green;
      color: blue;
    }
    color: red;
  }
  background: blue;
  .bar {
    color: green;
    color: blue;
    color: green;
  }
  caret-color: orange;
}

@keyframes my-animation {
  0% {
    color: color-mix(in oklab, var(--color-emerald-600) 0%, transparent);
  }
  100% {
    color: color-mix(in oklab, var(--color-emerald-600) 0%, transparent);
  }
}

.a {
  element {
    --x: 1;
  }
  .class {
    --x: 2;
  }
  #id {
    --x: 3;
  }
  :pseudo-class {
    --x: 4;
  }
  ::pseudo-element {
    --x: 5;
  }
  [attribute] {
    --x: 6;
  }
  * {
    --x: 7;
  }
}

/* Standalone */
& {
  --x: 1;
}

/* In an at-rule */
@supports (--y: 1) {
  & {
    --x: 2;
  }
}

/* With :is(…) */
:is(&) {
  --x: 3;
}

/* In an at-rule, with :is(…) */
@supports (--y: 2) {
  :is(&) {
    --x: 4;
  }
}

/* With multiple selectors */
&,
.a {
